def summarize_scores(scores, passing=60):
    passed = [score for score in scores if score >= passing]
    failed = [score for score in scores if score < passing]
    return {
        'total': len(scores),
        'passed_count': len(passed),
        'failed_count': len(failed),
        'passing': passing,
    }

print(summarize_scores([72, 44, 90, 61]))
